var containerElement = null;
var weatherCache = null;

Script.Inputs = {
    Mount: "signal",
    OnChangedPosition: "signal",
    Positions: "array",
    Latitude: "number",
    Longitude: "number"
};

Script.Signals = {
    Mount: function() { initContainer(); },
    OnChangedPosition: function() { updateWeather(); }
};

Script.Outputs = {
    Meteo: "string"
}

function initContainer() {
    containerElement = document.querySelector('.meteo_france');
    if (!containerElement) {
        console.warn("Noodl : Le conteneur '.meteo_france' est introuvable dans le DOM.");
        return;
    }
    containerElement.style.position = "relative";
    containerElement.style.overflow = "hidden";
    containerElement.style.borderRadius = "20px";
    containerElement.style.boxShadow = "0 12px 40px rgba(0,0,0,0.2)";
    containerElement.style.fontFamily = "'Segoe UI', system-ui, sans-serif";
    containerElement.style.minHeight = "220px";
    injectStyles();
    updateWeather();
}

function injectStyles() {
    if (document.getElementById('meteo-styles')) return;
    var s = document.createElement('style');
    s.id = 'meteo-styles';
    s.textContent = `
        .mw-root {
            width: 100%;
            height: 100%;
            background: linear-gradient(160deg, #0f2d4a 0%, #1a5276 45%, #2e86c1 80%, #7fb3d3 100%);
            color: #fff;
            box-sizing: border-box;
            user-select: none;
        }
        .mw-loader {
            display: flex;
            align-items: center;
            justify-content: center;
            height: 220px;
            flex-direction: column;
            gap: 12px;
        }
        .mw-spinner {
            width: 32px; height: 32px;
            border: 3px solid rgba(255,255,255,0.2);
            border-top-color: #fff;
            border-radius: 50%;
            animation: mw-spin 0.8s linear infinite;
        }
        @keyframes mw-spin { to { transform: rotate(360deg); } }
        .mw-spinner-label { font-size: 13px; opacity: 0.7; }
        .mw-error {
            display: flex; align-items: center; justify-content: center;
            height: 220px; font-size: 13px; opacity: 0.7; text-align: center; padding: 20px;
        }
        .mw-header {
            display: flex; align-items: center; gap: 6px;
            padding: 14px 16px 0;
            font-size: 12px; opacity: 0.75;
            white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
        }
        .mw-header svg { flex-shrink: 0; }
        .mw-main {
            display: flex; align-items: flex-start;
            padding: 10px 16px 12px;
            gap: 12px;
        }
        .mw-temp-block { display: flex; align-items: flex-start; line-height: 1; }
        .mw-temp { font-size: 58px; font-weight: 300; letter-spacing: -2px; }
        .mw-unit { font-size: 22px; font-weight: 300; margin-top: 8px; opacity: 0.85; }
        .mw-info { flex: 1; padding-top: 8px; }
        .mw-condition { font-size: 14px; font-weight: 500; opacity: 0.95; margin-bottom: 4px; }
        .mw-details { font-size: 11px; opacity: 0.7; display: flex; flex-direction: column; gap: 2px; }
        .mw-icon { font-size: 38px; line-height: 1; margin-top: 4px; }
        .mw-days {
            display: flex;
            border-top: 1px solid rgba(255,255,255,0.12);
        }
        .mw-day {
            flex: 1;
            display: flex; flex-direction: column; align-items: center;
            padding: 10px 4px 12px;
            cursor: pointer;
            border-right: 1px solid rgba(255,255,255,0.08);
            transition: background 0.15s;
            position: relative;
        }
        .mw-day:last-child { border-right: none; }
        .mw-day:hover { background: rgba(255,255,255,0.08); }
        .mw-day.active { background: rgba(255,255,255,0.14); }
        .mw-day.active::after {
            content: '';
            position: absolute;
            top: 0; left: 0; right: 0;
            height: 2px;
            background: rgba(255,255,255,0.7);
        }
        .mw-day-name { font-size: 11px; font-weight: 600; opacity: 0.65; text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 4px; }
        .mw-day-icon { font-size: 20px; margin-bottom: 4px; }
        .mw-day-max { font-size: 14px; font-weight: 600; }
        .mw-day-min { font-size: 11px; opacity: 0.6; }
        .mw-source {
            text-align: right;
            padding: 0 12px 8px;
            font-size: 9px;
            opacity: 0.35;
            letter-spacing: 0.3px;
        }
    `;
    document.head.appendChild(s);
}

var WMO_CODES = {
    0:  { label: "Ciel dégagé",          icon: "☀️" },
    1:  { label: "Peu nuageux",           icon: "🌤️" },
    2:  { label: "Partiellement nuageux", icon: "⛅" },
    3:  { label: "Couvert",               icon: "☁️" },
    45: { label: "Brouillard",            icon: "🌫️" },
    48: { label: "Brouillard givrant",    icon: "🌫️" },
    51: { label: "Bruine légère",         icon: "🌦️" },
    53: { label: "Bruine modérée",        icon: "🌦️" },
    55: { label: "Bruine dense",          icon: "🌧️" },
    61: { label: "Pluie légère",          icon: "🌧️" },
    63: { label: "Pluie modérée",         icon: "🌧️" },
    65: { label: "Pluie forte",           icon: "🌧️" },
    71: { label: "Neige légère",          icon: "🌨️" },
    73: { label: "Neige modérée",         icon: "❄️" },
    75: { label: "Neige forte",           icon: "❄️" },
    80: { label: "Averses légères",       icon: "🌦️" },
    81: { label: "Averses modérées",      icon: "🌧️" },
    82: { label: "Averses violentes",     icon: "⛈️" },
    95: { label: "Orage",                icon: "⛈️" },
    96: { label: "Orage avec grêle",     icon: "⛈️" },
    99: { label: "Orage fort avec grêle",icon: "⛈️" }
};

function wmo(code) {
    return WMO_CODES[code] || { label: "Inconnu", icon: "🌡️" };
}

function dayName(dateStr, index) {
    if (index === 0) return "Auj.";
    var d = new Date(dateStr);
    return d.toLocaleDateString('fr-FR', { weekday: 'short' }).replace('.', '');
}

function renderWidget(data, selectedIndex) {
    var daily = data.daily;
    var current = data.current_weather;

    var daysHTML = '';
    for (var i = 0; i < Math.min(daily.time.length, 5); i++) {
        var wmoDay = wmo(daily.weathercode[i]);
        var isActive = i === selectedIndex ? ' active' : '';
        daysHTML +=
            '<div class="mw-day' + isActive + '" data-index="' + i + '">' +
                '<div class="mw-day-name">' + dayName(daily.time[i], i) + '</div>' +
                '<div class="mw-day-icon">' + wmoDay.icon + '</div>' +
                '<div class="mw-day-max">' + Math.round(daily.temperature_2m_max[i]) + '°</div>' +
                '<div class="mw-day-min">' + Math.round(daily.temperature_2m_min[i]) + '°</div>' +
            '</div>';
    }

    var selWmo, selTemp, selWind, selRain, selHumidity;
    if (selectedIndex === 0) {
        selWmo = wmo(current.weathercode);
        selTemp = Math.round(current.temperature);
        selWind = Math.round(current.windspeed);
        selRain = Math.round(daily.precipitation_sum[0] || 0);
        selHumidity = daily.precipitation_probability_max ? daily.precipitation_probability_max[0] : null;
    } else {
        selWmo = wmo(daily.weathercode[selectedIndex]);
        selTemp = Math.round((daily.temperature_2m_max[selectedIndex] + daily.temperature_2m_min[selectedIndex]) / 2);
        selWind = daily.windspeed_10m_max ? Math.round(daily.windspeed_10m_max[selectedIndex]) : '—';
        selRain = Math.round(daily.precipitation_sum[selectedIndex] || 0);
        selHumidity = daily.precipitation_probability_max ? daily.precipitation_probability_max[selectedIndex] : null;
    }

    var detailsHTML =
        '<div>💨 Vent : ' + selWind + ' km/h</div>' +
        '<div>🌧️ Précip. : ' + selRain + ' mm</div>' +
        (selHumidity !== null ? '<div>💧 Prob. pluie : ' + selHumidity + '%</div>' : '');

    containerElement.innerHTML =
        '<div class="mw-root">' +
            '<div class="mw-header">' +
                '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="2.5" stroke-linecap="round"><circle cx="12" cy="12" r="3"/><line x1="12" y1="2" x2="12" y2="5"/><line x1="12" y1="19" x2="12" y2="22"/><line x1="2" y1="12" x2="5" y2="12"/><line x1="19" y1="12" x2="22" y2="12"/></svg>' +
                (data._addressLabel || (Math.abs(data.latitude).toFixed(2) + '°' + (data.latitude >= 0 ? 'N' : 'S') + ' · ' + Math.abs(data.longitude).toFixed(2) + '°' + (data.longitude >= 0 ? 'E' : 'O'))) +
            '</div>' +
            '<div class="mw-main">' +
                '<div class="mw-temp-block">' +
                    '<div class="mw-temp">' + selTemp + '</div>' +
                    '<div class="mw-unit">°C</div>' +
                '</div>' +
                '<div class="mw-icon">' + selWmo.icon + '</div>' +
                '<div class="mw-info">' +
                    '<div class="mw-condition">' + selWmo.label + '</div>' +
                    '<div class="mw-details">' + detailsHTML + '</div>' +
                '</div>' +
            '</div>' +
            '<div class="mw-days">' + daysHTML + '</div>' +
            '<div class="mw-source">Open-Meteo.com · CC BY 4.0</div>' +
        '</div>';

    containerElement.querySelectorAll('.mw-day').forEach(function(el) {
        el.addEventListener('click', function() {
            renderWidget(weatherCache, parseInt(el.getAttribute('data-index'), 10));
        });
    });

    var meteoToday = {
        condition: selWmo.label,
        icon: selWmo.icon,
        temperature: selTemp,
        wind: selWind,
        rain: selRain,
        humidity: selHumidity
    };
    Script.Outputs.Meteo = JSON.stringify(meteoToday);
}

function getAddressLabel(lat, lng, callback) {
    var url = "https://nominatim.openstreetmap.org/reverse" +
        "?lat=" + lat +
        "&lon=" + lng +
        "&format=json" +
        "&accept-language=fr";

    fetch(url, { headers: { 'User-Agent': 'NoodlWeatherWidget/1.0' } })
        .then(function(r) { return r.json(); })
        .then(function(data) {
            var addr = data.address || {};
            var label = addr.village || addr.town || addr.city || addr.municipality || addr.county || "";
            if (addr.postcode) label += (label ? ", " : "") + addr.postcode;
            callback(label || null);
        })
        .catch(function() { callback(null); });
}

function updateWeather() {
    var lat = NaN, lng = NaN;

    if (Script.Inputs.Latitude !== undefined && Script.Inputs.Longitude !== undefined) {
        lat = parseFloat(Script.Inputs.Latitude);
        lng = parseFloat(Script.Inputs.Longitude);
    }

    if ((isNaN(lat) || isNaN(lng)) && Script.Inputs.Positions) {
        var inputPositions = Script.Inputs.Positions;
        var rawArray = [];
        if (Array.isArray(inputPositions)) {
            rawArray = inputPositions;
        } else if (typeof inputPositions === "string") {
            try { rawArray = JSON.parse(inputPositions); } catch(e) { return; }
        } else if (typeof inputPositions === "object") {
            if (typeof inputPositions.toArray === 'function') rawArray = inputPositions.toArray();
            else if (inputPositions.items) rawArray = Array.isArray(inputPositions.items) ? inputPositions.items : [inputPositions.items];
            else if (inputPositions.latitude || inputPositions.lat) rawArray = [inputPositions];
            else if (inputPositions.attributes) rawArray = [inputPositions.attributes];
        }
        if (rawArray && rawArray.length > 0) {
            var d = rawArray[0].attributes ? rawArray[0].attributes : rawArray[0];
            if (d) { lat = parseFloat(d.lat || d.latitude); lng = parseFloat(d.lng || d.longitude); }
        }
    }

    if (!containerElement) return;
    if (isNaN(lat) || isNaN(lng)) {
        Script.Outputs.Meteo = "Erreur : Latitude ou longitude manquante.";
        containerElement.innerHTML =
            '<div class="mw-root"><div class="mw-error">' +
                '📍 Veuillez fournir une latitude et une longitude valides.' +
            '</div></div>';
        return;
    }

    containerElement.innerHTML =
        '<div class="mw-root"><div class="mw-loader">' +
            '<div class="mw-spinner"></div>' +
            '<div class="mw-spinner-label">Chargement météo...</div>' +
        '</div></div>';

    var coordLabel = Math.abs(lat).toFixed(2) + "°" + (lat >= 0 ? "N" : "S") + " · " + Math.abs(lng).toFixed(2) + "°" + (lng >= 0 ? "E" : "O");

    var weatherUrl = "https://api.open-meteo.com/v1/forecast" +
        "?latitude=" + lat +
        "&longitude=" + lng +
        "&current_weather=true" +
        "&daily=temperature_2m_max,temperature_2m_min,weathercode,precipitation_sum,windspeed_10m_max,precipitation_probability_max" +
        "&timezone=auto" +
        "&forecast_days=5";

    Promise.all([
        fetch(weatherUrl).then(function(r) { return r.json(); }),
        new Promise(function(resolve) { getAddressLabel(lat, lng, resolve); })
    ])
    .then(function(results) {
        var data = results[0];
        var address = results[1];
        data._addressLabel = coordLabel + (address ? "  ·  " + address : "");
        weatherCache = data;
        renderWidget(data, 0);
    })
    .catch(function() {
        Script.Outputs.Meteo = "Erreur : Impossible de charger la météo.";
        containerElement.innerHTML =
            '<div class="mw-root"><div class="mw-error">Impossible de charger la météo.<br>Vérifiez la connexion réseau.</div></div>';
    });
}

