Script.Inputs = {
    Mount:         "signal",
    Container:     "reference",
    ShowNotif:     "signal",
    Notifications: "array",
};
Script.Signals = {
    Mount:      function () { init(); },
    Destroy:    function () { destroy(); },
    ShowNotif:  function () { showNotifications(); }
};
Script.Outputs = {
    text: "string"
};

let wrapper = null;
let notifContainer = null;
let audioCtx = null;

// ─── INIT ─────────────────────────────────────────────────────────────────────
function init() {
    const ref = Script.Inputs.Container;
    if (!ref) { console.warn("Aucune ref valide"); return; }
    const div = ref.getDOMElement ? ref.getDOMElement() : ref;
    if (!div || !div.appendChild) { console.warn("DOM introuvable:", div); return; }

    wrapper = document.createElement("div");
    wrapper.style.cssText = `
        position: absolute;
        inset: 0;
        width: 100%;
        height: 100%;
        pointer-events: none;
        z-index: 9999;
        font-family: 'Georgia', serif;
    `;

    wrapper.innerHTML = `
        <style>
            @import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@300;400&display=swap');

            #agri-notif-container {
                position: absolute;
                top: 20px;
                left: 50%;
                transform: translateX(-50%);
                z-index: 99999;
                display: flex;
                flex-direction: column;
                align-items: center;
                gap: 10px;
                pointer-events: none;
                width: 100%;
                max-width: 460px;
                padding: 0 16px;
            }

            .agri-notif {
                width: 100%;
                pointer-events: all;
                border-radius: 14px;
                padding: 13px 16px 13px 14px;
