                background: rgba(200,180,10,0.3); color: #ffe566;
                border: 1px solid rgba(200,180,10,0.5);
            }

            .agri-notif.rappel {
                background: rgba(8, 20, 35, 0.92);
                border: 1px solid rgba(60, 140, 220, 0.35);
            }
            .agri-notif.rappel::before { background: linear-gradient(180deg, #4da6ff, #1a6fc4); }

            .agri-notif.succes {
                background: rgba(8, 25, 10, 0.92);
