// ─── AUDIO ────────────────────────────────────────────────────────────────────
function getAudioCtx() {
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    return audioCtx;
}

function playSound(type) {
    try {
        var ctx = getAudioCtx();

        var sounds = {
            'meteo-rouge': function () {
                [0, 0.18, 0.36].forEach(function (delay, i) {
                    var osc = ctx.createOscillator();
                    var gain = ctx.createGain();
                    osc.connect(gain);
                    gain.connect(ctx.destination);
                    osc.type = 'square';
                    osc.frequency.setValueAtTime(880 - i * 80, ctx.currentTime + delay);
                    gain.gain.setValueAtTime(0, ctx.currentTime + delay);
                    gain.gain.linearRampToValueAtTime(0.18, ctx.currentTime + delay + 0.01);
                    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + delay + 0.14);
                    osc.start(ctx.currentTime + delay);
                    osc.stop(ctx.currentTime + delay + 0.15);
                });
            },
            'meteo-orange': function () {
                [0, 0.25].forEach(function (delay) {
                    var osc = ctx.createOscillator();
                    var gain = ctx.createGain();
                    osc.connect(gain);
                    gain.connect(ctx.destination);
                    osc.type = 'sine';
                    osc.frequency.setValueAtTime(520, ctx.currentTime + delay);
                    osc.frequency.linearRampToValueAtTime(660, ctx.currentTime + delay + 0.18);
                    gain.gain.setValueAtTime(0, ctx.currentTime + delay);
                    gain.gain.linearRampToValueAtTime(0.12, ctx.currentTime + delay + 0.04);
                    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + delay + 0.22);
                    osc.start(ctx.currentTime + delay);
                    osc.stop(ctx.currentTime + delay + 0.23);
                });
            },
            'meteo-jaune': function () {
                var osc = ctx.createOscillator();
                var gain = ctx.createGain();
                osc.connect(gain);
                gain.connect(ctx.destination);
                osc.type = 'sine';
                osc.frequency.setValueAtTime(600, ctx.currentTime);
                osc.frequency.linearRampToValueAtTime(720, ctx.currentTime + 0.2);
                gain.gain.setValueAtTime(0, ctx.currentTime);
                gain.gain.linearRampToValueAtTime(0.1, ctx.currentTime + 0.03);
                gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.28);
                osc.start(ctx.currentTime);
                osc.stop(ctx.currentTime + 0.29);
            },
            'rappel': function () {
                var osc = ctx.createOscillator();
                var gain = ctx.createGain();
                osc.connect(gain);
                gain.connect(ctx.destination);
                osc.type = 'sine';
                osc.frequency.setValueAtTime(880, ctx.currentTime);
                osc.frequency.exponentialRampToValueAtTime(660, ctx.currentTime + 0.3);
                gain.gain.setValueAtTime(0, ctx.currentTime);
                gain.gain.linearRampToValueAtTime(0.1, ctx.currentTime + 0.02);
                gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.5);
                osc.start(ctx.currentTime);
                osc.stop(ctx.currentTime + 0.5);
            },
            'succes': function () {
                [[523, 0], [659, 0.12], [784, 0.24]].forEach(function (note) {
                    var osc = ctx.createOscillator();
                    var gain = ctx.createGain();
                    osc.connect(gain);
                    gain.connect(ctx.destination);
                    osc.type = 'sine';
                    osc.frequency.setValueAtTime(note[0], ctx.currentTime + note[1]);
                    gain.gain.setValueAtTime(0, ctx.currentTime + note[1]);
                    gain.gain.linearRampToValueAtTime(0.09, ctx.currentTime + note[1] + 0.02);
                    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + note[1] + 0.18);
                    osc.start(ctx.currentTime + note[1]);
                    osc.stop(ctx.currentTime + note[1] + 0.2);
                });
            },
            'info': function () {
                var osc = ctx.createOscillator();
                var gain = ctx.createGain();
                osc.connect(gain);
                gain.connect(ctx.destination);
                osc.type = 'sine';
                osc.frequency.setValueAtTime(440, ctx.currentTime);
                gain.gain.setValueAtTime(0, ctx.currentTime);
                gain.gain.linearRampToValueAtTime(0.08, ctx.currentTime + 0.01);
                gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.25);
                osc.start(ctx.currentTime);
                osc.stop(ctx.currentTime + 0.26);
            }
        };

        var fn = sounds[type] || sounds['info'];
        fn();
    } catch (e) {
        console.warn('Audio non disponible :', e);
    }
}

// ─── NOTIFICATIONS ────────────────────────────────────────────────────────────
function showNotifications() {
    if (!notifContainer) return;

    var items = Script.Inputs.Notifications;

    if (!Array.isArray(items)) {
        if (items && typeof items === 'object') {
            items = [items];
        } else {
            console.warn("Notifications: valeur invalide", items);
            return;
        }
    }

    items.forEach(function (item, index) {
        setTimeout(function () {
            showSingleNotification(item);
        }, index * 150);
    });
}

function showSingleNotification(item) {
    if (!notifContainer) return;

    var type    = ((item.type    || 'info') + '').toLowerCase();
    var titre   = item.title   || 'Notification';
    var message = item.message || '';

    var durations = {
        'meteo-rouge':  8000,
        'meteo-orange': 6000,
        'meteo-jaune':  5000,  
        'rappel':       5000,
        'succes':       4000,
        'info':         4000
    };
    var duration = durations[type] || 5000;

    var icons = {
        'meteo-rouge':  '🌩️',
        'meteo-orange': '⛈️',
        'meteo-jaune':  '🌧️',  // ← ajout
        'rappel':       '📅',
        'succes':       '✅',
        'info':         'ℹ️'
    };
    var icon = icons[type] || 'ℹ️';

    var badges = {
        'meteo-rouge':  '<span class="agri-notif-badge">Vigilance rouge</span>',
        'meteo-orange': '<span class="agri-notif-badge">Vigilance orange</span>',
        'meteo-jaune':  '<span class="agri-notif-badge">Vigilance jaune</span>' 
    };
    var badge = badges[type] || '';

    var notif = document.createElement('div');
    notif.className = 'agri-notif ' + type;

    notif.innerHTML =
        '<span class="agri-notif-icon">' + icon + '</span>' +
        '<div class="agri-notif-body">' +
            '<p class="agri-notif-titre">' + titre + '</p>' +
            (message ? '<p class="agri-notif-msg">' + message + '</p>' : '') +
            badge +
        '</div>' +
        '<button class="agri-notif-close" title="Fermer">✕</button>' +
        '<div class="agri-notif-progress" style="animation-duration:' + duration + 'ms"></div>';

    notifContainer.appendChild(notif);

    requestAnimationFrame(function () {
        requestAnimationFrame(function () {
            notif.classList.add('visible');
        });
    });

    playSound(type);

    var timer = setTimeout(function () { closeNotif(notif); }, duration);

    notif.querySelector('.agri-notif-close').addEventListener('click', function (e) {
        e.stopPropagation();
        clearTimeout(timer);
        closeNotif(notif);
    });

    notif.addEventListener('click', function () {
        clearTimeout(timer);
        closeNotif(notif);
    });
}

function closeNotif(notif) {
    notif.classList.remove('visible');
    notif.classList.add('hiding');
    setTimeout(function () {
        if (notif && notif.parentNode) notif.parentNode.removeChild(notif);
    }, 300);
}

