    Check: function() {
        const savedToken = localStorage.getItem('user_token');
        const savedDate = localStorage.getItem('TTL'); // Ta date enregistrée (ex: format ISO)
        
        if (savedToken && savedDate) {
            const expiryTime = new Date(savedDate).getTime(); // Conversion de la date en millisecondes
            const now = new Date().getTime(); // Heure actuelle en millisecondes
            
            if (now < expiryTime) {
                console.log(savedToken);
                Script.Outputs.Token = savedToken;
                Script.Outputs.Found();
                return;
            }
        }
        
        // Si on arrive ici, c'est que le token est absent ou expiré
        console.log("Session expirée ou invalide.");
        localStorage.removeItem('user_token');
        localStorage.removeItem('TTL');
        Script.Outputs.Token = "";
        Script.Outputs.NotFound();
    }
};

