// Add custom code to convert the response content to outputs
//
//*Response.status    The status code of the response
//*Response.content   The content of the response as a javascript
//                    object.
//*Response.request   The request object that resulted in the response.
//
//*Inputs and *Outputs contain the inputs and outputs of the node.
if (Response.status === 200 && Response.content) {
    // On expose le token reçu pour pouvoir le câbler visuellement
    localStorage.setItem("user_token", Response.content.access_token)
    localStorage.setItem('TTL', Response.content.expire);
}

if (Response.status !== 200 && Response.content) {
    // On expose le message d'erreur dans les Outputs officiels du nœud
    if (Response.content.detail) {
        Outputs.errormsg = Response.content.detail;
    } else {
        Outputs.errormsg = "Une erreur inconnue est survenue.";
    }

}

