// ─── INIT CARTE ───────────────────────────────────────────────────────────────
function initMap() {
    var el = document.querySelector('.zone-carte-osm');
    if (!el) return;
    injectStyles();
    el.style.position = "relative";
    el.style.overflow = "hidden";
    el.innerHTML = '';

    // Écran de chargement temporaire
    var loader = document.createElement('div');
    loader.className = 'map-loader-overlay';
    loader.innerHTML = '<div class="map-spinner"></div><div class="map-loader-text" id="map-loader-lbl">Chargement de la carte</div>';
    el.appendChild(loader);

    var count = 0;
    var loaderLbl = el.querySelector('#map-loader-lbl');
    var loaderTimer = setInterval(function() {
        count = (count + 1) % 4;
        if (loaderLbl) loaderLbl.textContent = "Chargement de la carte" + ".".repeat(count);
    }, 400);

    function loadMapLibre(cb) {
        if (window.maplibregl) { cb(); return; }
        var css = document.createElement('link');
        css.rel = 'stylesheet';
        css.href = 'https://unpkg.com/maplibre-gl@4.7.1/dist/maplibre-gl.css';
        document.head.appendChild(css);
        var js = document.createElement('script');
        js.src = 'https://unpkg.com/maplibre-gl@4.7.1/dist/maplibre-gl.js';
        js.onload = cb;
        document.head.appendChild(js);
    }

    loadMapLibre(function () {
        var mapDiv = document.createElement('div');
        mapDiv.id = 'maplibre-map';
        mapDiv.style.cssText = 'width:100%;height:100%;position:absolute;top:0;left:0;';
        el.appendChild(mapDiv);

        // ── Panneau calques (radar uniquement)
        var panel = document.createElement('div');
        panel.className = 'layer-panel';
        function mkBtn(id, dotId, icon, label) {
            var b = document.createElement('button');
            b.className = 'layer-btn';
            b.id = id;
            b.innerHTML = '<span class="btn-icon">' + icon + '</span><span>' + label + '</span><span class="btn-dot off" id="' + dotId + '"></span>';
            return b;
        }
        var bRadar = mkBtn('btn-radar', 'dot-radar', '🌧', 'Radar pluie');
        bRadar.addEventListener('click', toggleRadar);
        panel.appendChild(bRadar);
        el.appendChild(panel);

        // ── Barre radar
        var bar = document.createElement('div');
        bar.className = 'radar-bar hidden';
        bar.id = 'radar-bar';
        bar.innerHTML =
            '<span class="radar-badge">Radar</span>' +
            '<button class="radar-btn" id="radar-prev">&#9664;</button>' +
            '<button class="radar-btn" id="radar-play">&#9654;</button>' +
            '<button class="radar-btn" id="radar-next">&#9654;</button>' +
            '<div class="radar-timeline" id="radar-tl">' +
                '<div class="radar-tl-fill" id="radar-fill" style="width:0%"></div>' +
                '<div class="radar-tl-thumb" id="radar-thumb" style="left:0%"></div>' +
            '</div>' +
            '<span class="radar-time" id="radar-time">--:--</span>';
        el.appendChild(bar);

        // ── Carte
        map = new maplibregl.Map({
            container: 'maplibre-map',
            style: {
                version: 8,
                sources: {
                    osm: {
                        type: 'raster',
                        tiles: [
                            'https://a.tile.openstreetmap.org/{z}/{x}/{y}.png',
                            'https://b.tile.openstreetmap.org/{z}/{x}/{y}.png'
                        ],
                        tileSize: 256,
                        attribution: '© OpenStreetMap',
                        minzoom: 0,
                        maxzoom: 19
                    }
                },
                layers: [{
                    id: 'osm',
                    type: 'raster',
                    source: 'osm',
                    minzoom: 0,
                    maxzoom: 24
                }]
            },
            center: [currentLng, currentLat],
            zoom: 6,
            maxZoom: 19
        });

        map.addControl(new maplibregl.NavigationControl(), 'bottom-right');

        map.on('load', function () {
            document.getElementById('radar-prev').addEventListener('click', function () { stopAnimation(); stepRadar(-1); });
            document.getElementById('radar-next').addEventListener('click', function () { stopAnimation(); stepRadar(1); });
            document.getElementById('radar-play').addEventListener('click', togglePlay);
            document.getElementById('radar-tl').addEventListener('click', function (e) {
                var rect = this.getBoundingClientRect();
                var ratio = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
                stopAnimation();
                animationPosition = Math.round(ratio * (radarFrames.length - 1));
                showRadarFrame(animationPosition);
            });

            loadRadarData();
            drawPositions_force();
            console.log("load data");

            // Fin du chargement : arrêt du timer et suppression progressive
            clearInterval(loaderTimer);
            loader.classList.add('hidden');
            setTimeout(function() { loader.remove(); }, 400);

            Script.Outputs.LoadMap();
            Script.Outputs.IsLoadedMap = true;
        });

        setInterval(loadRadarData, 5 * 60 * 1000);
    });
}

// ─── WAYPOINTS ────────────────────────────────────────────────────────────────
function addSearchMarker(lon, lat, name) {
    var el = document.createElement('div');
    el.className = 'wp-marker';
    el.style.background = '#e74c3c';
    new maplibregl.Marker({ element: el })
        .setLngLat([lon, lat])
        .setPopup(new maplibregl.Popup({ offset: 18 }).setHTML(
            '<div class="popup-body"><h4>📍 Recherche</h4><div class="popup-row"><span>' + name.substring(0, 40) + '</span></div></div>'
        ))
        .addTo(map);
}
function drawPositions() {
    if (!map) return;
    drawPositions_force();
}

function drawPositions_force() {
    var inputPositions = Script.Inputs.Positions;
    if (!inputPositions) { console.log("no input"); return; };

    console.log(inputPositions);

    var rawArray = [];

    if (typeof inputPositions === "object" && !Array.isArray(inputPositions)) {
        if (typeof inputPositions.toArray === 'function') {
            rawArray = inputPositions.toArray();
        } else if (inputPositions.items) {
            rawArray = Array.isArray(inputPositions.items) ? inputPositions.items : [inputPositions.items];
        } else if (inputPositions.targetLatitude || inputPositions.lat || inputPositions.latitude) {
            rawArray = [inputPositions];
        } else {
            var keys = Object.keys(inputPositions);
            if (keys.length > 0 && typeof inputPositions[keys[0]] === 'object') {
                rawArray = keys.map(function(k) { return inputPositions[k]; });
            } else {
                rawArray = [inputPositions];
            }
        }
    } else if (Array.isArray(inputPositions)) {
        rawArray = inputPositions;
    } else if (typeof inputPositions === "string") {
        try { rawArray = JSON.parse(inputPositions); } catch (e) { return; }
    }

    console.log(rawArray);

    if (!rawArray || !rawArray.length) return;

    mapLayers.forEach(function (m) { m.remove(); });
    mapLayers = [];
    var bounds = null;

    rawArray.forEach(function (item) {
        var data = item && item.attributes ? item.attributes : item;
        if (!data) return;
        var lat = parseFloat(data.targetLatitude || data.lat || data.latitude);
        var lng = parseFloat(data.targetLongitude || data.lng || data.longitude);
        var label = data.text || data.name || data.label || data.title || "Waypoint";

        if (!isNaN(lat) && !isNaN(lng)) {
            var el = document.createElement('div');
            el.className = 'wp-marker';
            var marker = new maplibregl.Marker({ element: el })
                .setLngLat([lng, lat])
                .setPopup(new maplibregl.Popup({ offset: 18 }).setHTML(
                    '<div class="popup-body"><h4>' + label + '</h4>' +
                    '<div class="popup-row"><span>Latitude</span><span class="popup-val">' + lat.toFixed(5) + '</span></div>' +
                    '<div class="popup-row"><span>Longitude</span><span class="popup-val">' + lng.toFixed(5) + '</span></div>' +
                    '</div>'
                ))
                .addTo(map);
            mapLayers.push(marker);
            if (!bounds) bounds = new maplibregl.LngLatBounds([lng, lat], [lng, lat]);
            else bounds.extend([lng, lat]);
        }
    });

    if (bounds) {
        map.fitBounds(bounds, { padding: 60, maxZoom: 14, duration: 800 });
        var center = map.getCenter();
        currentLat = center.lat; currentLng = center.lng;
        Script.Outputs.currentLat = currentLat;
        Script.Outputs.currentLng = currentLng;
    }
}

// ─── RADAR RAINVIEWER ─────────────────────────────────────────────────────────
function loadRadarData() {
    if (!map || !map.loaded()) return;
    fetch('https://api.rainviewer.com/public/weather-maps.json')
        .then(function (r) { return r.json(); })
        .then(function (data) {
            radarApiData = data;
            var newFrames = data.radar.past || [];
            if (!newFrames.length) return;

            // Nettoie les anciens layers
            Object.keys(radarLayers).forEach(function (i) {
                if (map.getLayer(radarLayers[i])) map.removeLayer(radarLayers[i]);
                if (map.getSource('radar-src-' + i)) map.removeSource('radar-src-' + i);
            });
            radarLayers = {};

            newFrames.forEach(function (frame, i) {
                var sid = 'radar-src-' + i;
                var lid = 'radar-lyr-' + i;
                map.addSource(sid, {
                    type: 'raster',
                    tiles: [data.host + frame.path + '/512/{z}/{x}/{y}/' + COLOR_SCHEME + '/1_1.png'],
                    tileSize: 512,
                    attribution: 'RainViewer',
                    minzoom: 0,
                    maxzoom: 6
                });
                map.addLayer({
                    id: lid,
                    type: 'raster',
                    source: sid,
                    minzoom: 0,
                    maxzoom: 24,
                    paint: { 'raster-opacity': 0 }
                });
                radarLayers[i] = lid;
            });

            radarFrames = newFrames;

            var now = Math.floor(Date.now() / 1000);
            var bestIdx = radarFrames.length - 1;
            var bestDiff = Infinity;
            radarFrames.forEach(function (f, i) {
                var diff = Math.abs(f.time - now);
                if (diff < bestDiff) { bestDiff = diff; bestIdx = i; }
            });

            radarLoaded = true;
            animationPosition = bestIdx;
            if (radarVisible) showRadarFrame(animationPosition);
        })
        .catch(function (e) { console.warn('Radar indisponible', e); });
}

function showRadarFrame(index) {
    if (!radarFrames.length) return;
    Object.keys(radarLayers).forEach(function (i) {
        if (map.getLayer(radarLayers[i])) map.setPaintProperty(radarLayers[i], 'raster-opacity', 0);
    });
    if (radarVisible && radarLayers[index] && map.getLayer(radarLayers[index])) {
        map.setPaintProperty(radarLayers[index], 'raster-opacity', RADAR_OPACITY);
    }
    var pct = radarFrames.length > 1 ? (index / (radarFrames.length - 1)) * 100 : 0;
    var fill   = document.getElementById('radar-fill');
    var thumb = document.getElementById('radar-thumb');
    var lbl   = document.getElementById('radar-time');
    if (fill)  fill.style.width = pct + '%';
    if (thumb) thumb.style.left = pct + '%';
    if (lbl && radarFrames[index]) {
        var d = new Date(radarFrames[index].time * 1000);
        lbl.textContent = d.getHours().toString().padStart(2,'0') + ':' + d.getMinutes().toString().padStart(2,'0');
    }
}

function stepRadar(dir) {
    animationPosition = (animationPosition + dir + radarFrames.length) % radarFrames.length;
    showRadarFrame(animationPosition);
}

function startAnimation() {
    if (animationTimer) clearInterval(animationTimer);
    var interval = Math.max(400, Math.round(8000 / Math.max(radarFrames.length, 1)));
    animationTimer = setInterval(function () {
        animationPosition = (animationPosition + 1) % radarFrames.length;
        showRadarFrame(animationPosition);
    }, interval);
    isPlaying = true;
    var btn = document.getElementById('radar-play');
    if (btn) btn.innerHTML = '&#9646;&#9646;';
}

function stopAnimation() {
    if (animationTimer) { clearInterval(animationTimer); animationTimer = null; }
    isPlaying = false;
    var btn = document.getElementById('radar-play');
    if (btn) btn.innerHTML = '&#9654;';
}

function togglePlay() { if (isPlaying) stopAnimation(); else startAnimation(); }

function toggleRadar() {
    radarVisible = !radarVisible;
    var btn = document.getElementById('btn-radar');
    var dot = document.getElementById('dot-radar');
    var bar = document.getElementById('radar-bar');
    if (radarVisible) {
        btn.classList.add('active'); dot.className = 'btn-dot blue';
        bar.classList.remove('hidden');
        if (radarLoaded) showRadarFrame(animationPosition);
    } else {
        btn.classList.remove('active'); dot.className = 'btn-dot off';
        bar.classList.add('hidden');
        Object.keys(radarLayers).forEach(function (i) {
            if (map && map.getLayer(radarLayers[i])) map.setPaintProperty(radarLayers[i], 'raster-opacity', 0);
        });
        stopAnimation();
    }
}

// ─── SETTER POSITIONS ─────────────────────────────────────────────────────────
Script.Setters.Positions = function () {
    pendingPositions = true;
    if (!map || !map.loaded()) return;
    drawPositions();
};

