};

// 3. Gestion de la logique du signal
Script.Signals = {
    Logout: function() {
        console.log("=== DÉCONNEXION EN COURS ===");

        try {
            // Nettoyage des données de session locales
            localStorage.removeItem('user_token');
            localStorage.removeItem('TTL');
            console.log("LocalStorage nettoyé avec succès.");

            console.log("Redirection vers la page de Login...");
            
            // Envoi du signal de sortie vers Noodl
            Script.Outputs.OnLogoutSuccess();

        } catch (error) {
            console.error("Erreur lors de la déconnexion :", error);
            
            // En cas d'erreur critique, on force quand même la sortie pour ne pas bloquer l'utilisateur
            Script.Outputs.OnLogoutSuccess();
        }
    }
};

