Script.Inputs = {
    Mount: "signal", 
};
Script.Signals = {
    Mount: function() {
        const vgMenu = document.querySelector(".test");
        const vgButton = document.querySelector(".button_burger");

        // Vérification de sécurité : on s'assure que les éléments existent
        if (!vgMenu || !vgButton) {
            console.warn("Les éléments .test ou .button_burger ne sont pas dans le DOM.");
            return; 
        }

        let show = false;
        let bInAnimation = false;
        function toggleMenu() {
            if (bInAnimation) { console.log("animation"); return; }
            show = !show;
            console.log(show);
            // Application de la taille
            vgMenu.style.height = show ? "100%" : "30px";
            vgMenu.style.transition = "all 0.5s ease-in-out";
            vgMenu.style.backgroundColor = show ? "rgb(255, 255, 255)" : "rgb(0, 0, 0, 0)";

            const vgMap = document.querySelector(".zone-carte-osm");
            if (show && vgMap) { vgMap.style.zIndex = -1 }; 

            bInAnimation = true
            vgMenu.addEventListener("transitionend", () => {
                if (!show && vgMap) {
                    vgMap.style.zIndex = 1
                }

                bInAnimation = false
            });
        }

        // On attache l'événement uniquement au bouton
        vgButton.addEventListener("click", toggleMenu);

        vgMenu.style.transition = "none";
        vgMenu.style.height = show ? "100%" : "30px";
    }
}

